questionvariables.text:
/* Design backwards: curated [throw speed v, target rate targ] pairs. AROC over
   [a,b] for s(t)=v t-5 t^2 is v-5(a+b); a valid interval needs a+b=(v-targ)/5,
   and every pair below leaves room for one strictly inside [0, tmax], tmax=v/5.
   Dimensions of variation: v in {20,25,30}; targ in {0,+-5,+-10,+-15}, with
   targ=0 the headline net-displacement case. */
data : [[20,0],[20,5],[20,-5],[20,10],[20,-10],[20,15],[20,-15],
        [25,0],[25,5],[25,-5],[25,10],[25,-10],[25,15],[25,-15],
        [30,0],[30,5],[30,-5],[30,10],[30,-10],[30,15],[30,-15]];
row  : data[rand(length(data))+1];
v    : row[1];              /* throw speed (m/s) */
targ : row[2];              /* target average rate the student must hit */
tmax : v/5;                 /* landing time; domain of the model is [0, tmax] */

apb  : (v - targ)/5;        /* required a+b for a correct interval */

/* One sample correct interval, symmetric about apb/2, snapped to the 0.1 grid.
   Used only in the worked solution and question tests - marking checks a property. */
a_ta : (apb/2) - 1/2;
b_ta : (apb/2) + 1/2;

/* Sign-flipped sample interval (average rate = -targ): the mirror of the correct
   interval across the peak, so it also lies inside [0, tmax]. Used only by the
   "missed the negative" question test. */
a_sf : ((v + targ)/5)/2 - 1/2;
b_sf : ((v + targ)/5)/2 + 1/2;

/* Model-answer point coordinates for the two hidden inputs. */
ta1 : [a_ta, v*a_ta - 5*a_ta^2];   /* [a, s(a)] */
ta2 : [b_ta, v*b_ta - 5*b_ta^2];   /* [b, s(b)] */

/* Board bounds derived from v (peak height is v^2/20 at t=v/10). */
peak : v^2/20;
ytop : peak + 3;
ybot : -3;

/* Initial glider positions: an interval whose average rate is NOT the target
   (so doing nothing scores zero). Shift the sample interval by 1 s; if that
   would fall off the domain, shift the other way. Its rate is targ-5 or targ+5. */
a0 : if b_ta + 1 <= tmax then a_ta + 1 else a_ta - 1;
b0 : if b_ta + 1 <= tmax then b_ta + 1 else b_ta - 1;

/* Worked-solution note: the zero-target case gets the net-displacement insight. */
extranote : if targ = 0
  then "<p>Because the target is \\(0\\) m/s, the stone ends the interval at exactly the height it started &mdash; the <em>net</em> displacement is zero. This does <strong>not</strong> mean the stone was still: it is rising at \\(t=a\\) and falling at \\(t=b\\), moving the whole time. The flat secant records only that it came back to the same height, which is why an average rate can hide what happens inside the interval.</p>"
  else "<p>A positive target means the stone is higher at \\(b\\) than at \\(a\\) on average (rising); a negative target means it is lower (falling). The steeper the secant, the larger the average rate.</p>";

feedbackvariables.text:
/* Read the x-coordinates the student chose off the two bound points. */
sax : ans1[1];               /* a = start time */
sbx : ans2[1];               /* b = end time */
dt  : sbx - sax;             /* Delta t (may be 0 if same time twice) */
/* Average rate over the student's interval, guarded against Delta t = 0 so the
   feedback variables never divide by zero (the degenerate case is caught first). */
srate : if abs(dt) > 0.001
          then ((v*sbx - 5*sbx^2) - (v*sax - 5*sax^2)) / dt
          else 0;
/* Correct-answer feedback text. When the target is zero, append the
   net-displacement insight from the "stone in flight" activity. */
hitmsg : if targ = 0
  then "<p>Correct &mdash; the secant is flat, so the average rate is \\(0\\) m/s. Notice the stone is <em>not</em> still: it is rising at \\(t=a\\) and falling at \\(t=b\\). The average rate is zero only because the stone returns to the same height, giving zero <strong>net</strong> displacement over the interval.</p>"
  else "<p>Correct &mdash; the slope of your green secant is the average rate of change over your interval, and it matches the target. Notice that other intervals would give the same average rate.</p>";
/* Sign diagnostic: a student can reach the right magnitude but the wrong sign
   (e.g. +5 m/s when the target is -5 m/s) - "missing the negative". */
negtarg : -targ;
signhint : if targ < 0
  then "slide your interval to the <em>right</em> of the peak, where the stone is coming back down"
  elseif targ > 0
  then "keep your interval to the <em>left</em> of the peak, where the stone is still rising"
  else "widen or shift the interval by dragging \\(A\\) and \\(B\\)";
